       "过拉格艾尔大桥、穿马克维尔街道追朱朱，到螺旋山谷打七一式机神兵；先清三只触手，红色物理战技用「神速」回避。",
       "追到螺旋山谷上层再打一次七一式机神兵，随后打神秘的费斯。"
