  bondMeta:{
    title:"全牵绊对话",
    tab:"牵绊",
    chars:["修尔克","莱恩","菲奥伦","丹邦","卡露娜","力奇","梅莉亚"],
    note:"63 条牵绊对话（玩家常说的「羁绊对话／羁绊任务」）。每条需要指定两人同时在队，并达到牵绊等级：黄 0–999、绿 1000–1999、青 2000–2999、紫 3000–4999、粉 5000。标「仅夜间」的要把时间切到晚上；组头的黄框是区域时限/解锁提醒。",
    foot:"攻略站普遍认为牵绊对话不会永久错过；只有「某日，于公园」初版会在９号殖民地遭袭后被替换成另一版。每条对话有两次二选一，选对 +50、选错 -50，结束再 +300，净赚 200–400。送礼、带两人做任务、连锁/激励/复活等刷法见「急救与技巧」。牵绊对话不计入 480 条任务统计；「相连的未来」的 Quiet Moments 无牵绊要求，不在本表。"
  },
