  npcMeta:{
    title:"全 NPC 一览",
    tab:"NPC",
    races:["荷姆斯","海恩塔","机神界人","诺彭"],
    areas:["９号殖民地","灰烬洞窟","巨神脚","６号殖民地","磷光之地扎托尔","玛格纳原始森林","边境村","艾尔特海","皇都阿卡莫托","瓦拉克雪山","坠落巨臂","机神界区域"],
    note:"164 名有名 NPC（中文维基 NPC 命名空间全量）。活动时间是游戏内时钟；地点为常去地点，NPC 会在附近走动。同一 NPC 可能有多条记录，通常是剧情、任务分支或移民前后；按当前进度取用。标「状态」的条目请以游戏内当前状态为准；部分 NPC 会随任务完成、移民或剧情消失/移动，具体以任务页和游戏内为准。",
    foot:"6:00–6:00 多为全天或任务期间出现。交易只列件数与最高星级，完整交易表以游戏内为准；任务名按本页任务表的委托人匹配。种族/性别/年龄取该 NPC 的第一条记录。"
  },
  tips:[
    {t:"普攻自动，战技取消后摇",a:"普通攻击是自动的；放战技可以取消普攻后摇。走位到侧面或背面再放战技，伤害更高。"},
    {t:"连锁攻击看颜色",a:"连锁攻击里同色连携数越高，伤害倍率越高，最高 +7。别把队伍计量表浪费在低倍率连携上。"},
    {t:"预知怎么解",a:"红色物理战技用「神速」；白色天赋战技用「护盾」；紫色以太战技可用「装甲」减伤；灵气和反噬用「破坏」；机神兵用「附魔」。"},
    {t:"机神兵要先倒地",a:"机神兵不进入倒地状态打不出伤害；用「附魔」后其他武器也能打伤。"},
    {t:"队伍计量表怎么攒",a:"暴击、特效、突发牵绊和战技都能涨队伍计量表；突发牵绊按得准涨得更多。连锁攻击前先攒满。"},
    {t:"士气别一直低",a:"连续失误会降士气、拉低命中；队友表情阴沉时用「激励」恢复普通士气。"},
    {t:"越级惩罚很重",a:"等级低于敌人 3 级以上，命中和伤害会暴跌；任务给的经验很多，卡关先清一圈任务。"},
    {t:"多用穿越旅行",a:"在 菜单 > 区域地图 传到去过的地标；城镇 NPC 有作息，切时间比满地图找快。"},
    {t:"牵绊图和地域评价值",a:"和有名 NPC 对话会登记牵绊图；交易和完成任务涨地域评价值，很多任务解锁靠它。"},
    {t:"NPC 作息看「NPC」页",a:"164 名有名 NPC 按区域列出，标了活动时间、常去地点、种族、喜欢的礼物和交易最高星级。同一 NPC 可能有多条作息，按当前剧情/移民状态取用；6:00–6:00 多为全天或任务期间。"},
    {t:"时钟图标=限时",a:"任务菜单里带时钟图标的是限时任务；进新区域先接，别等主线推完。"},
    {t:"二选一不可逆",a:"二选一任务完成不可逆；本页勾一条会锁另一条，想换分支先取消。"},
    {t:"殖民地6 是长期工程",a:"先开复兴，再按住宅/商业/自然/特殊升级；移民和素材要慢慢补，别想一次做完。"},
    {t:"插槽和宝珠",a:"装备插槽可以装宝珠；卖装备时已装的宝珠会退回。"},
    {t:"刷牵绊：送礼最快",a:"菜单 > 牵绊图 > 队伍，按 Y 送礼。喜欢的收集品 +18~30，讨厌的会倒扣；「迷恋药」对所有人 +100，但要殖民地6 五星交易和顶级素材，属于后期手段。早期好刷的：修尔克「蓝色链条」、莱恩「烈性高丽菜」、卡露娜「尖锐蔓越莓」、丹邦「草原蜻蜓」、力奇「尺蠖」、梅莉亚「杜宾柯基犬」、菲奥伦「可爱草莓」。"},
    {t:"刷牵绊：带两人做任务",a:"一起出战的成员完成任务会涨 20–100 牵绊；想刷哪两人，就把他们固定在队伍里清支线。480 条任务本身就是最大的牵绊来源，顺路做比专门刷快。"},
    {t:"刷牵绊：战斗里顺手攒",a:"连锁攻击给全队 +10；激励（突发牵绊）按得准 +10~30；复活或治疗战斗不能、气绝、转倒的队友 +20。刷低等级杂兵时顺手做，积少成多。"},
    {t:"刷牵绊：先低后高",a:"每条牵绊对话两次二选一各 ±50，结束再 +300，净赚 200–400，是单次收益最高的来源。先看黄/绿门槛的，再滚雪球看紫/粉；63 条全看完足够把多组关系拉满。皇都的 6 条建议第１５章前清。"},
    {t:"珍稀种掉好货",a:"地图上的珍稀种会掉好装备；等级不够先绕，别硬打。"},
    {t:"计时挑战",a:"计时挑战完成课题可得诺彭水晶和道具，诺彭水晶可换强力装备。"},
    {t:"多存档",a:"限时任务和最终章前手动存；选错二选一或漏了时限，读档比二周目快。"},
    {t:"相连的未来",a:"43 个支线无时限、无二选一；部分计时挑战课题需要追加内容才能解锁。"}
  ],
  qa:[
    {q:"全任务一周目能做完吗？",a:"不能。480 个任务里有 25 组二选一（50 条），每组只能完成一条，所以单周目上限是 455 条；NS2 版多一条任务，上限 456。二周目可以补另一分支，但任务完成记录会重置。"},
    {q:"怎么一眼看出哪些任务会消失？",a:"游戏任务菜单里带时钟图标的就是限时任务。本页「全任务 → 限时」会把 130 条全列出来，并标出期限事件；进下一章前先清对应区域的限时。"},
    {q:"二选一任务选错了怎么办？",a:"本页勾选一条后会自动锁定另一条，防止误勾。想换分支，先取消已勾的那条，再勾另一条；游戏内一旦完成就不可逆，只能二周目补。"},
    {q:"殖民地6 复兴值得做吗？",a:"值得。它给商店、移民、任务、隐藏性格和强力装备，还是全任务完成度的一大块。本页「收集清单」按住宅/商业/自然/特殊四类列了 Lv1–5 的金钱和素材。"},
    {q:"地域评价值和牵绊怎么升？",a:"做该区域任务、和 NPC 对话、完成牵绊图上的连接、用交换（交易）都会涨。很多任务要求地域评价值达到 1–5 星，或某个 NPC 已登记在牵绊图；卡任务时先看任务菜单的接受条件。"},
    {q:"牵绊对话会漏吗？",a:"会。牵绊对话要求特定章节、队伍组合和牵绊等级，部分在后期区域关闭后不可看。建议每到一个新区域，用不同队伍组合把当地的牵绊对话点一遍；本页不逐条列，优先清带时限的区域。"},
    {q:"等级不够怎么办？",a:"任务给的经验很多，先把当前区域的普通任务清一圈；打不过先做当前区域任务，再回头打 Boss。"},
    {q:"NS1 和 NS2 版有什么区别？",a:"NS2 Edition 有最高 4K / 60fps（手提 1080p）和载具「以太喷射器」，并新增 1 个巨神脚任务（<i class='jp'>トテツモナイハツメイ</i>，靠近逃生艇营地的诺彭工程师触发）。任务总数从 480 变 481，单周目上限从 455 变 456；其余任务、时限、二选一结构不变。"},
    {q:"「相连的未来」值得打吗？",a:"值得。它是后日谈，43 个支线全部无时限、无二选一；部分计时挑战课题也需要追加内容才能解锁。没有二周目，想重打只能新开。"},
    {q:"二周目继承什么？",a:"Switch 版会自动继承可继承的内容，且没有数量限制；贵重品、挑战模式、牵绊图、任务、地图、牵绊话题和珍稀种讨伐标记不继承。二周目的主要意义是补另一分支、补漏掉的牵绊对话和隐藏性格。"},
    {q:"隐藏性格和隐藏战技怎么拿？",a:"全部来自支线：每条隐藏性格对应一条角色支线，两个隐藏蒙纳多战技也来自支线。它们不影响主线通关，但影响全任务和终盘强度；清区域任务时优先做带角色名的支线。"},
    {q:"任务菜单里的「剧情」「突发」是什么意思？",a:"「剧情任务」是主线自动接、自动完成的条目；「突发任务」是在特定地点/条件下突然出现的任务，很多同时是限时。本页分别用「剧情」「限时」标记，方便你决定要不要专门跑一趟。"}
  ],
