  bosses:[
    {n:"黑色的费斯（初战）",s:"９号殖民地 · 第２章",t:"抵抗破防，用连锁攻击破防再倒地；削掉一半 HP 结束。"},
    {n:"蜘蛛女王",s:"灰烬洞窟 · 第３章",t:"蜘蛛粉碎Ⅰ用「护盾」；先清小蜘蛛，避免被围。"},
    {n:"七一式机神兵 / 神秘的费斯",s:"巨神脚 · 第４章",t:"先清触手，红色物理战技用「神速」，白色天赋战技用「护盾」。"},
    {n:"佐德",s:"中央采矿场 · 第５章",t:"第一战用连锁攻击破防再倒地，靠杂兵攒队伍计量表；站他侧后；第二战附魔输出，提防狂暴化。"},
    {n:"扎托尔的守护者",s:"磷光之地 · 第６章",t:"破防、倒地无效；带毒防御宝珠和解除减益战技；龙卷回旋靠睡眠或盾弹应对。"},
    {n:"塔鲁可 + 索利多姆·特雷西亚",s:"海恩塔墓地 · 第８章",t:"先打倒特雷西亚；「破坏」或梅莉亚的心灵爆裂消除读取思考；修尔克打不伤塔鲁可。"},
    {n:"黑色的费斯（监狱岛）",s:"监狱岛 · 第９章",t:"附魔后全队可打；削掉约八成 HP 结束。"},
    {n:"穆姆卡（雪山）",s:"瓦拉克雪山 · 第１０章",t:"靠蒙纳多Ⅱ、附魔或倒地才打得动；破防成功率约 50%；削掉约两成 HP 结束。"},
    {n:"穆姆卡（机神形态）",s:"大剑溪谷 · 第１１章",t:"还有量产型费斯×2；带解毒手段；HP 低时连锁攻击倒地；打倒穆姆卡即结束。"},
    {n:"绿色的费斯",s:"机神界区域 · 第１３章",t:"先靠近；线性镭射Ⅳ和速射炮可躲掩体；削掉约三成 HP 结束。"},
    {n:"加德",s:"中央工厂 · 第１４章",t:"线性镭射V 用「护盾」；要昏厥抗性；第二战先打防卫式·SHAME，以太干扰器后防镭射弹。"},
    {n:"外典产生器",s:"外典产生室 · 第１５章",t:"会张防护罩并用多种减益；HP 所剩无几时连发磁场展开·零式。"},
    {n:"伊达波思",s:"机神界中枢 · 第１５章",t:"只能面向巨神一侧；先清召唤的机神兵；能量装置 120 秒内全破坏，否则游戏结束。"},
    {n:"使徒罗兰",s:"巨神的心脏 · 第１７章",t:"打倒新星后物理耐性大降；让梅莉亚用以太攻击；别进绿色池子。"},
    {n:"使徒迪克森",s:"监狱岛 · 第１７章",t:"连打两战；提防混沌制裁；带战技封印、倒地、吹飞、麻痹抗性。"},
    {n:"萨扎",s:"记忆空间 · 最终决战",t:"「护盾」最好到 IX；先打守护者；第二战趁「黑洞」到「重构世界」之间猛攻。"},
    {n:"雾之王",s:"相连的未来 · 最终战",t:"先清雾兽，梅莉亚以太输出，修尔克用蒙纳多清雾；具体机制未逐条核对。"}
  ],
